 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the non-background patterned object and extend it toward the edge
    # opposite the monochrome boundary, with the marker color 8.
    colors = {}
    for row in grid:
        for x in row:
            colors[x] = colors.get(x, 0) + 1
    bg = max(colors, key=colors.get)
    full_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    full_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    if full_rows:
        sep = full_rows[0]
        sep_color = grid[sep][0]
        obj = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, sep_color)]
        if obj:
            rr = max(r for r,c in obj) + 1
            if rr < h:
                out = [row[:] for row in grid]
                out[rr] = [8] * w
                return out
    if full_cols:
        sep = full_cols[0]
        sep_color = grid[0][sep]
        obj = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, sep_color)]
        if obj:
            cc = max(c for r,c in obj) + 1
            if cc < w:
                out = [row[:] for row in grid]
                for r in range(h):
                    out[r][cc] = 8
                return out
    return [row[:] for row in grid]

